import pytest
from sessions import remove_expired

def test_remove_expired_mixed_cases():
    # Prepare a sessions dict with a mix of expired and active sessions
    sessions = {
        "a": {"expires_at": 100.0},
        "b": {"expires_at": 200.0},
        "c": {"expires_at": 300.0},
        "d": {"expires_at": 400.0},
    }
    # Current time is 250, so "a", "b", and "c" (<=250) should be removed
    now = 250.0
    removed = remove_expired(sessions, now)
    assert removed == 3
    # Only the session with expires_at > now should remain
    assert sessions == {"d": {"expires_at": 400.0}}

def test_remove_expired_all_expired():
    sessions = {
        1: {"expires_at": 10},
        2: {"expires_at": 20},
        3: {"expires_at": 30},
    }
    now = 100  # all sessions are expired
    removed = remove_expired(sessions, now)
    assert removed == 3
    assert sessions == {}

def test_remove_expired_none_expired():
    sessions = {
        "x": {"expires_at": 500},
        "y": {"expires_at": 600},
    }
    now = 400
    removed = remove_expired(sessions, now)
    assert removed == 0
    # Dict should be unchanged (same object, same content)
    assert sessions == {"x": {"expires_at": 500}, "y": {"expires_at": 600}}

def test_remove_expired_boundary_condition():
    sessions = {
        "exact": {"expires_at": 1000.0},
        "later": {"expires_at": 1000.1},
    }
    now = 1000.0
    removed = remove_expired(sessions, now)
    # The entry with expires_at exactly equal to now should be removed (<=)
    assert removed == 1
    assert sessions == {"later": {"expires_at": 1000.1}}

def test_remove_expired_large_dict_no_error():
    # Build a larger dict to ensure the function does not raise during iteration
    sessions = {i: {"expires_at": i * 10} for i in range(1000)}
    now = 5000  # roughly half should be removed
    expected_removed = len([i for i in sessions if sessions[i]["expires_at"] <= now])
    removed = remove_expired(sessions, now)
    assert removed == expected_removed
    # Verify that all remaining entries have expires_at > now
    assert all(session["expires_at"] > now for session in sessions.values())

import pytest

from sessions import remove_expired


def test_remove_expired_mixed_cases():
    # Prepare a dict with mixed expiration times
    sessions = {
        "session1": {"expires_at": 100.0},
        "session2": {"expires_at": 200.0},
        "session3": {"expires_at": 150.0},
        "session4": {"expires_at": 250.0},
    }
    # now is 150, so session1 (100) and session3 (150) should be removed (<= now)
    removed = remove_expired(sessions, now=150.0)
    assert removed == 2
    # Remaining keys should be the ones not expired
    assert set(sessions.keys()) == {"session2", "session4"}
    # Ensure the values are untouched for remaining sessions
    assert sessions["session2"]["expires_at"] == 200.0
    assert sessions["session4"]["expires_at"] == 250.0


def test_remove_expired_all_expired():
    sessions = {
        "a": {"expires_at": 1},
        "b": {"expires_at": 2},
        "c": {"expires_at": 3},
    }
    removed = remove_expired(sessions, now=10)
    assert removed == 3
    assert sessions == {}


def test_remove_expired_none_expired():
    sessions = {
        "x": {"expires_at": 1000},
        "y": {"expires_at": 2000},
    }
    original = sessions.copy()
    removed = remove_expired(sessions, now=500)
    assert removed == 0
    # The dict should be unchanged (same objects)
    assert sessions == original
    # Ensure it is the same dict instance (in‑place mutation test)
    assert sessions is original


def test_remove_expired_empty_dict():
    sessions = {}
    removed = remove_expired(sessions, now=123)
    assert removed == 0
    assert sessions == {}


def test_remove_expired_boundary_condition():
    # expires_at exactly equal to now should be considered expired
    sessions = {"edge": {"expires_at": 42.0}, "future": {"expires_at": 43.0}}
    removed = remove_expired(sessions, now=42.0)
    assert removed == 1
    assert "edge" not in sessions
    assert "future" in sessions


def test_remove_expired_returns_int():
    sessions = {"a": {"expires_at": 0}}
    result = remove_expired(sessions, now=1)
    assert isinstance(result, int)
    assert result == 1

import copy
import pytest
from sessions import remove_expired

def test_remove_some_expired():
    sessions = {
        "a": {"expires_at": 10},
        "b": {"expires_at": 20},
        "c": {"expires_at": 5},
    }
    original = copy.deepcopy(sessions)
    removed = remove_expired(sessions, now=10)
    # Sessions with expires_at <= 10 are "a" and "c"
    assert removed == 2
    assert isinstance(removed, int)
    assert "a" not in sessions
    assert "c" not in sessions
    assert sessions == {"b": original["b"]}

def test_remove_none_expired():
    sessions = {
        "a": {"expires_at": 15},
        "b": {"expires_at": 20},
    }
    copy_sessions = sessions.copy()
    removed = remove_expired(sessions, now=10)
    assert removed == 0
    assert isinstance(removed, int)
    assert sessions == copy_sessions

def test_remove_all_expired():
    sessions = {
        "a": {"expires_at": 1},
        "b": {"expires_at": 2},
    }
    removed = remove_expired(sessions, now=5)
    assert removed == 2
    assert isinstance(removed, int)
    assert sessions == {}

def test_remove_empty_dict():
    sessions = {}
    removed = remove_expired(sessions, now=0)
    assert removed == 0
    assert isinstance(removed, int)
    assert sessions == {}

def test_expired_equal_now():
    sessions = {"a": {"expires_at": 10}}
    removed = remove_expired(sessions, now=10)
    assert removed == 1
    assert isinstance(removed, int)
    assert sessions == {}

def test_missing_expires_at_raises():
    sessions = {"a": {"not_expires": 5}}
    with pytest.raises(KeyError):
        remove_expired(sessions, now=10)

def test_mutation_is_in_place():
    sessions = {"a": {"expires_at": 0}, "b": {"expires_at": 100}}
    ref = sessions
    removed = remove_expired(sessions, now=1)
    assert ref is sessions  # same object
    assert removed == 1
    assert isinstance(removed, int)
    assert sessions == {"b": {"expires_at": 100}}

def test_large_number_of_sessions():
    # 1000 sessions, half expired
    sessions = {f"s{i}": {"expires_at": i} for i in range(1000)}
    removed = remove_expired(sessions, now=499)
    assert removed == 500
    assert isinstance(removed, int)
    # Remaining keys should be 500..999
    assert set(sessions.keys()) == {f"s{i}" for i in range(500, 1000)}
